//! The domino-reduction (DR) group `<U, D, R2, L2, F2, B2>` as coordinates + tables.
//! (Port of `drcore.h`.)
//!
//! Conventions (everything else is derived from these few lines):
//!
//! ```text
//!   corner positions : 0 UFR 1 UFL 2 UBL 3 UBR 4 DFR 5 DFL 6 DBL 7 DBR
//!   U/D-layer edges  : 0 UF 1 UL 2 UB 3 UR 4 DF 5 DL 6 DB 7 DR
//!   E-slice edges    : 0 FR 1 FL 2 BL 3 BR
//!   Moves            : 0 U 1 U2 2 U' 3 D 4 D2 5 D' 6 R2 7 L2 8 F2 9 B2
//!                      (U clockwise seen from above: UFR->UFL->UBL->UBR)
//! ```
//!
//! * A state is "which piece sits at each position" (pieces are named by their home position),
//!   see [`St`].  In the DR group no piece is ever twisted or flipped, so three permutations
//!   (8 corners, 8 U/D-layer edges, 4 E-slice edges) describe a state completely.
//! * Applying a move that carries position `p` to position `t[p]`:  `new[t[p]] = old[p]`.
//! * If A and B are move sequences, `state(A then B)[pos] = state(A)[ state(B)[pos] ]`.
//! * A permutation is stored as a number, its lexicographic rank ([`rank_perm`]): the three
//!   *coordinates* `c` (0..40320), `e` (0..40320), `s` (0..24).  Only states with
//!   `parity(c) ^ parity(e) == parity(s)` are reachable, which gives
//!   40320 * 40320 * 24 / 2 = 19,508,428,800 states.
//! * The 16 symmetries are the rotations/reflections of the cube that keep the U/D axis:
//!   generated by y (quarter rotation about U/D), x2 (half rotation about R/L) and the
//!   mirror L<->R.  A symmetry S acts on a state by conjugation, `S a S^-1`.

/// Number of corner permutations (8!).
pub const NC: usize = 40320;
/// Number of permutations of the eight U/D-layer edges (8!).
pub const NE: usize = 40320;
/// Number of permutations of the four E-slice edges (4!).
pub const NS: usize = 24;
/// The ten DR moves.
pub const NMOVES: usize = 10;
/// The sixteen symmetries that keep the U/D axis.
pub const NSYM: usize = 16;

pub const MOVE_NAME: [&str; NMOVES] = ["U", "U2", "U'", "D", "D2", "D'", "R2", "L2", "F2", "B2"];
/// Inverse of each move.  (Part of the model; not needed by the current subcommands.)
#[allow(dead_code)]
pub const MOVE_INV: [usize; NMOVES] = [2, 1, 0, 5, 4, 3, 6, 7, 8, 9];
/// Quarter turns: U, U', D, D'.
pub const MOVE_IS_QT: [bool; NMOVES] = [
    true, false, true, true, false, true, false, false, false, false,
];
/// Face of each move: 0 U, 1 D, 2 R, 3 L, 4 F, 5 B.  (Part of the model; not needed by the current subcommands.)
#[allow(dead_code)]
pub const MOVE_FACE: [usize; NMOVES] = [0, 0, 0, 1, 1, 1, 2, 3, 4, 5];
/// Moves `FIRST_SIDE_MOVE..NMOVES` are the side half turns R2 L2 F2 B2.  Each of them swaps two
/// E-slice edges, so it flips the parity of the E-slice permutation; U and D moves do not.
pub const FIRST_SIDE_MOVE: usize = 6;

/// 1 if move `m` flips the E-slice parity (a side half turn), else 0.
#[inline]
pub fn e_parity_flip(m: usize) -> usize {
    (m >= FIRST_SIDE_MOVE) as usize
}

/// A position map `t`: whatever sits at position `p` is carried to position `t[p]`
/// (separately for corners, U/D-layer edges and E-slice edges).
struct PosMap {
    c: [u8; 8],
    e: [u8; 8],
    s: [u8; 4],
}

// Position maps of the generating moves.
const MAP_U: PosMap = PosMap {
    c: [1, 2, 3, 0, 4, 5, 6, 7],
    e: [1, 2, 3, 0, 4, 5, 6, 7],
    s: [0, 1, 2, 3],
};
// D clockwise seen from below: DFL->DFR->DBR->DBL ; DF->DR->DB->DL
const MAP_D: PosMap = PosMap {
    c: [0, 1, 2, 3, 7, 4, 5, 6],
    e: [0, 1, 2, 3, 7, 4, 5, 6],
    s: [0, 1, 2, 3],
};
const MAP_R2: PosMap = PosMap {
    c: [7, 1, 2, 4, 3, 5, 6, 0],
    e: [0, 1, 2, 7, 4, 5, 6, 3],
    s: [3, 1, 2, 0],
};
const MAP_L2: PosMap = PosMap {
    c: [0, 6, 5, 3, 4, 2, 1, 7],
    e: [0, 5, 2, 3, 4, 1, 6, 7],
    s: [0, 2, 1, 3],
};
const MAP_F2: PosMap = PosMap {
    c: [5, 4, 2, 3, 1, 0, 6, 7],
    e: [4, 1, 2, 3, 0, 5, 6, 7],
    s: [1, 0, 2, 3],
};
const MAP_B2: PosMap = PosMap {
    c: [0, 1, 7, 6, 4, 5, 3, 2],
    e: [0, 1, 6, 3, 4, 5, 2, 7],
    s: [0, 1, 3, 2],
};

// Position maps of the generating symmetries: y, x2 and the mirror L<->R.
const SYM_Y: PosMap = PosMap {
    c: [1, 2, 3, 0, 5, 6, 7, 4],
    e: [1, 2, 3, 0, 5, 6, 7, 4],
    s: [1, 2, 3, 0],
};
const SYM_X2: PosMap = PosMap {
    c: [7, 6, 5, 4, 3, 2, 1, 0],
    e: [6, 5, 4, 7, 2, 1, 0, 3],
    s: [3, 2, 1, 0],
};
const SYM_M: PosMap = PosMap {
    c: [1, 0, 3, 2, 5, 4, 7, 6],
    e: [0, 3, 2, 1, 4, 7, 6, 5],
    s: [1, 0, 3, 2],
};

/// A DR state: `c[pos]`, `e[pos]`, `s[pos]` = the piece sitting at position `pos`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct St {
    pub c: [u8; 8],
    pub e: [u8; 8],
    pub s: [u8; 4],
}

impl St {
    /// The solved cube.
    pub const ID: St = St {
        c: [0, 1, 2, 3, 4, 5, 6, 7],
        e: [0, 1, 2, 3, 4, 5, 6, 7],
        s: [0, 1, 2, 3],
    };

    fn apply_map(self, t: &PosMap) -> St {
        let mut r = St::ID;
        for p in 0..8 {
            r.c[t.c[p] as usize] = self.c[p];
            r.e[t.e[p] as usize] = self.e[p];
        }
        for p in 0..4 {
            r.s[t.s[p] as usize] = self.s[p];
        }
        r
    }

    /// The state after applying move `m` (0..10) to `self`.
    pub fn apply_move(self, m: usize) -> St {
        match m {
            0 => self.apply_map(&MAP_U),
            1 => self.apply_move(0).apply_move(0),
            2 => self.apply_move(0).apply_move(0).apply_move(0),
            3 => self.apply_map(&MAP_D),
            4 => self.apply_move(3).apply_move(3),
            5 => self.apply_move(3).apply_move(3).apply_move(3),
            6 => self.apply_map(&MAP_R2),
            7 => self.apply_map(&MAP_L2),
            8 => self.apply_map(&MAP_F2),
            _ => self.apply_map(&MAP_B2),
        }
    }

    /// `state(A then B)` where `self` = state(A) and `b` = state(B).
    pub fn mul(self, b: St) -> St {
        let mut r = St::ID;
        for p in 0..8 {
            r.c[p] = self.c[b.c[p] as usize];
            r.e[p] = self.e[b.e[p] as usize];
        }
        for p in 0..4 {
            r.s[p] = self.s[b.s[p] as usize];
        }
        r
    }

    /// The inverse state (the state reached by the inverse move sequence).
    pub fn inv(self) -> St {
        let mut r = St::ID;
        for p in 0..8 {
            r.c[self.c[p] as usize] = p as u8;
            r.e[self.e[p] as usize] = p as u8;
        }
        for p in 0..4 {
            r.s[self.s[p] as usize] = p as u8;
        }
        r
    }

    /// The state with coordinates (`c`, `e`, `s`).
    pub fn unrank(c: usize, e: usize, s: usize) -> St {
        St {
            c: unrank_perm(c),
            e: unrank_perm(e),
            s: unrank_perm(s),
        }
    }
}

// ---- permutation ranking (lexicographic / Lehmer)

const FACT: [usize; 9] = [1, 1, 2, 6, 24, 120, 720, 5040, 40320];

/// Lexicographic rank of the permutation `p` among the permutations of `0..p.len()`.
pub fn rank_perm(p: &[u8]) -> usize {
    let n = p.len();
    let mut r = 0;
    for i in 0..n {
        let k = p[i + 1..].iter().filter(|&&x| x < p[i]).count();
        r += k * FACT[n - 1 - i];
    }
    r
}

/// The permutation of `0..N` with lexicographic rank `r` (inverse of [`rank_perm`]).
pub fn unrank_perm<const N: usize>(mut r: usize) -> [u8; N] {
    let mut p = [0u8; N];
    let mut used = [false; 8];
    for i in 0..N {
        let mut k = r / FACT[N - 1 - i];
        r %= FACT[N - 1 - i];
        // the (k+1)-th value not used so far
        let mut j = 0;
        loop {
            if !used[j] {
                if k == 0 {
                    break;
                }
                k -= 1;
            }
            j += 1;
        }
        p[i] = j as u8;
        used[j] = true;
    }
    p
}

/// Parity of a permutation: 0 even, 1 odd.
pub fn perm_parity(p: &[u8]) -> u8 {
    let mut par = 0;
    let mut seen = [false; 8];
    for i in 0..p.len() {
        if !seen[i] {
            let (mut j, mut len) = (i, 0usize);
            while !seen[j] {
                seen[j] = true;
                j = p[j] as usize;
                len += 1;
            }
            par ^= ((len + 1) & 1) as u8; // a cycle of even length is an odd permutation
        }
    }
    par
}

/// The move, symmetry, inverse and parity tables on coordinates (the global tables of `drcore.h`).
///
/// Tables indexed `[m][x]` / `[sym][x]` give the coordinate after move `m` / after conjugation by `sym`.
// Not every table is read by the current subcommands; they are all kept, as in the C header.
#[allow(dead_code)]
pub struct Core {
    /// `cmove[m][c]`: corner coordinate after move `m`.
    pub cmove: Vec<[u16; NC]>,
    /// `emove[m][e]`: U/D-edge coordinate after move `m`.
    pub emove: Vec<[u16; NE]>,
    /// `smove[m][s]`: E-slice coordinate after move `m`.
    pub smove: [[u8; NS]; NMOVES],
    /// `csym[S][c]`: corner coordinate of `S a S^-1`.
    pub csym: Vec<[u16; NC]>,
    pub esym: Vec<[u16; NE]>,
    pub ssym: [[u8; NS]; NSYM],
    /// Coordinates of the inverse permutation.
    pub cinv: Vec<u16>,
    pub einv: Vec<u16>,
    pub sinv: [u8; NS],
    /// Permutation parities (0 even, 1 odd).
    pub cpar: Vec<u8>,
    pub epar: Vec<u8>,
    pub spar: [u8; NS],
    /// Position maps of the 16 symmetries.
    /// Index = `mir*8 + x2*4 + ypow`, meaning S = M^mir * X2^x2 * Y^ypow as position maps composed left to right.
    symc: [[u8; 8]; NSYM],
    syme: [[u8; 8]; NSYM],
    syms: [[u8; 4]; NSYM],
    /// `sym_move[S][m]`: the move `S m S^-1`.
    pub sym_move: [[usize; NMOVES]; NSYM],
    /// Inverse of each symmetry.
    pub sym_inv: [usize; NSYM],
    /// `sym_mul[S][T]`: first S, then T.
    pub sym_mul: [[usize; NSYM]; NSYM],
}

impl Core {
    /// Build all tables (the C `dr_init`).
    pub fn new() -> Core {
        // symmetry group elements: index = mir*8 + x2*4 + ypow
        let mut symc = [[0u8; 8]; NSYM];
        let mut syme = [[0u8; 8]; NSYM];
        let mut syms = [[0u8; 4]; NSYM];
        for sym in 0..NSYM {
            let mut c: [u8; 8] = std::array::from_fn(|p| p as u8);
            let mut e = c;
            let mut s: [u8; 4] = std::array::from_fn(|p| p as u8);
            let mut then = |g: &PosMap| {
                for p in 0..8 {
                    c[p] = g.c[c[p] as usize];
                    e[p] = g.e[e[p] as usize];
                }
                for p in 0..4 {
                    s[p] = g.s[s[p] as usize];
                }
            };
            if sym & 8 != 0 {
                then(&SYM_M);
            }
            if sym & 4 != 0 {
                then(&SYM_X2);
            }
            for _ in 0..(sym & 3) {
                then(&SYM_Y);
            }
            symc[sym] = c;
            syme[sym] = e;
            syms[sym] = s;
        }

        let mut core = Core {
            cmove: vec![[0u16; NC]; NMOVES],
            emove: vec![[0u16; NE]; NMOVES],
            smove: [[0u8; NS]; NMOVES],
            csym: vec![[0u16; NC]; NSYM],
            esym: vec![[0u16; NE]; NSYM],
            ssym: [[0u8; NS]; NSYM],
            cinv: vec![0u16; NC],
            einv: vec![0u16; NE],
            sinv: [0u8; NS],
            cpar: vec![0u8; NC],
            epar: vec![0u8; NE],
            spar: [0u8; NS],
            symc,
            syme,
            syms,
            sym_move: [[0; NMOVES]; NSYM],
            sym_inv: [0; NSYM],
            sym_mul: [[0; NSYM]; NSYM],
        };

        // corners and U/D edges use the same numbering scheme, so one loop fills both sets of tables
        for c in 0..NC {
            let a = St::unrank(c, c, c % NS);
            core.cpar[c] = perm_parity(&a.c);
            core.epar[c] = core.cpar[c];
            let iv = a.inv();
            core.cinv[c] = rank_perm(&iv.c) as u16;
            core.einv[c] = core.cinv[c];
            for m in 0..NMOVES {
                let b = a.apply_move(m);
                core.cmove[m][c] = rank_perm(&b.c) as u16;
                core.emove[m][c] = rank_perm(&b.e) as u16;
            }
            for sym in 0..NSYM {
                let b = core.conj(a, sym);
                core.csym[sym][c] = rank_perm(&b.c) as u16;
                core.esym[sym][c] = rank_perm(&b.e) as u16;
            }
        }
        for s in 0..NS {
            let a = St::unrank(0, 0, s);
            core.spar[s] = perm_parity(&a.s);
            core.sinv[s] = rank_perm(&a.inv().s) as u8;
            for m in 0..NMOVES {
                core.smove[m][s] = rank_perm(&a.apply_move(m).s) as u8;
            }
            for sym in 0..NSYM {
                core.ssym[sym][s] = rank_perm(&core.conj(a, sym).s) as u8;
            }
        }

        // how symmetries act on moves, their inverses and products
        let gen: [St; NMOVES] = std::array::from_fn(|m| St::ID.apply_move(m));
        for sym in 0..NSYM {
            for m in 0..NMOVES {
                let b = core.conj(gen[m], sym);
                match (0..NMOVES).rev().find(|&k| b == gen[k]) {
                    Some(k) => core.sym_move[sym][m] = k,
                    None => fatal!("symmetry {} does not map move {} to a move", sym, m),
                }
            }
            for t in 0..NSYM {
                // first `sym`, then `t`
                let c: [u8; 8] = std::array::from_fn(|p| core.symc[t][core.symc[sym][p] as usize]);
                match (0..NSYM).rev().find(|&w| c == core.symc[w]) {
                    Some(w) => core.sym_mul[sym][t] = w,
                    None => fatal!("symmetry set not closed"),
                }
                if core.sym_mul[sym][t] == 0 {
                    core.sym_inv[sym] = t;
                }
            }
        }
        core
    }

    /// The conjugate `S a S^-1`: the state `a` as seen after turning/mirroring the whole cube by symmetry `sym`.
    pub fn conj(&self, a: St, sym: usize) -> St {
        let (sc, se, ss) = (&self.symc[sym], &self.syme[sym], &self.syms[sym]);
        let mut r = St::ID;
        for p in 0..8 {
            r.c[sc[p] as usize] = sc[a.c[p] as usize];
            r.e[se[p] as usize] = se[a.e[p] as usize];
        }
        for p in 0..4 {
            r.s[ss[p] as usize] = ss[a.s[p] as usize];
        }
        r
    }
}

/// Parse a sequence of DR moves (accepts `'` and `2`, also the Unicode right quote U+2019 as prime).
///
/// Every byte that is not a face letter is skipped.  At most `maxn` moves are kept (further ones are
/// dropped silently, as in the C code).  Returns `None` if a side face (R L F B) is not a half turn.
pub fn parse_moves(txt: &[u8], maxn: usize) -> Option<Vec<usize>> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < txt.len() {
        let face = match txt[i] {
            b'U' => 0,
            b'D' => 1,
            b'R' => 2,
            b'L' => 3,
            b'F' => 4,
            b'B' => 5,
            _ => {
                i += 1;
                continue;
            }
        };
        i += 1;
        let (mut two, mut prime) = (false, false);
        loop {
            let rest = &txt[i..];
            if rest.first() == Some(&b'2') {
                two = true;
                i += 1;
            } else if rest.first() == Some(&b'\'') {
                prime = true;
                i += 1;
            } else if rest.starts_with(&[0xE2, 0x80, 0x99]) {
                prime = true;
                i += 3;
            } else {
                break;
            }
        }
        let m = match face {
            0 => {
                if two {
                    1
                } else if prime {
                    2
                } else {
                    0
                }
            }
            1 => {
                if two {
                    4
                } else if prime {
                    5
                } else {
                    3
                }
            }
            _ => {
                if !two {
                    return None;
                }
                4 + face
            }
        };
        if out.len() < maxn {
            out.push(m);
        }
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rank_and_unrank_are_inverse() {
        for r in (0..NC).step_by(97) {
            assert_eq!(rank_perm(&unrank_perm::<8>(r)), r);
        }
        for r in 0..NS {
            assert_eq!(rank_perm(&unrank_perm::<4>(r)), r);
        }
    }

    #[test]
    fn moves_have_the_right_order() {
        for m in 0..NMOVES {
            let order = if MOVE_IS_QT[m] { 4 } else { 2 };
            let mut a = St::ID;
            for _ in 0..order {
                a = a.apply_move(m);
            }
            assert_eq!(a, St::ID);
            assert_eq!(St::ID.apply_move(m).apply_move(MOVE_INV[m]), St::ID);
        }
    }

    #[test]
    fn parse_moves_examples() {
        assert_eq!(
            parse_moves(b"U R2 U' F2 D2 B2 L2 D\n", 512),
            Some(vec![0, 6, 2, 8, 4, 9, 7, 3])
        );
        assert_eq!(
            parse_moves("U\u{2019} D\u{2019}".as_bytes(), 512),
            Some(vec![2, 5])
        );
        assert_eq!(parse_moves(b"U R", 512), None);
        assert_eq!(parse_moves(b"U D U D", 2), Some(vec![0, 3]));
    }
}
